<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Hash;use Endroid\QrCode\Builder\Builder;use PhpOffice\PhpSpreadsheet\IOFactory;use PhpOffice\PhpSpreadsheet\Spreadsheet;use PhpOffice\PhpSpreadsheet\Writer\Xlsx;use Barryvdh\DomPDF\Facade\Pdf;
class SchoolResultController extends Controller{
private function auth(Request $r,$admin=false){$id=$r->session()->get('admin_id');$u=$id?DB::table('admins')->find($id):null;if(!$u||!$u->active)abort(response()->json(['success'=>false,'message'=>'Authentication required.'],401));if($admin&&$u->role!=='admin')abort(response()->json(['success'=>false,'message'=>'Admin access required.'],403));return $u;}
private function grade($m,$f){$p=$m/$f*100;return $p>=80?['A+',5]:($p>=70?['A',4]:($p>=60?['A-',3.5]:($p>=50?['B',3]:($p>=40?['C',2]:($p>=33?['D',1]:['F',0])))));} 
private function finalGpa($rows){$main=$rows->where('is_fourth_subject',0);if(!$main->count()||$main->contains(fn($x)=>$x->grade==='F'))return[0,'F','Fail'];$sum=$main->sum('grade_point')+$rows->where('is_fourth_subject',1)->sum(fn($x)=>max(0,$x->grade_point-2));$g=min(5,round($sum/$main->count(),2));$gr=$g>=5?'A+':($g>=4?'A':($g>=3.5?'A-':($g>=3?'B':($g>=2?'C':($g>=1?'D':'F')))));return[$g,$gr,'Pass'];}
private function process($subs,$entries){$out=[];$seen=[];foreach($entries as $e){$s=$subs->firstWhere('id',(int)($e['subject_id']??0));if(!$s)abort(response()->json(['success'=>false,'message'=>'Invalid subject.'],400));if(isset($seen[$s->id]))abort(response()->json(['success'=>false,'message'=>'Duplicate subject.'],400));$seen[$s->id]=1;$m=$e['marks']??null;if($m===''||$m===null||!is_numeric($m)||$m<0||$m>$s->full_marks)abort(response()->json(['success'=>false,'message'=>'Invalid marks for '.$s->subject_name.'.'],400));[$g,$p]=$this->grade((float)$m,$s->full_marks);$out[]=(object)['subject_id'=>$s->id,'marks'=>(float)$m,'grade'=>$g,'grade_point'=>$p,'is_fourth_subject'=>strtolower($s->subject_type)==='fourth'?1:0];}return[$out,$this->finalGpa(collect($out))];}
public function login(Request $r){$u=DB::table('admins')->whereRaw('LOWER(username)=?',[strtolower(trim($r->input('username','')) )])->first();if(!$u||!$u->active||!Hash::check($r->input('password',''),$u->password))return response()->json(['success'=>false,'message'=>'Invalid username or password.'],401);$r->session()->regenerate();$r->session()->put('admin_id',$u->id);DB::table('admins')->where('id',$u->id)->update(['last_login'=>now()]);return response()->json(['success'=>true,'message'=>'Login successful.','username'=>$u->username,'role'=>$u->role,'must_change_password'=>(bool)$u->must_change_password]);}
public function logout(Request $r){$r->session()->invalidate();$r->session()->regenerateToken();return response()->json(['success'=>true,'message'=>'Logout successful.']);}
public function me(Request $r){$id=$r->session()->get('admin_id');$u=$id?DB::table('admins')->find($id):null;return response()->json($u?['loggedIn'=>true,'username'=>$u->username,'role'=>$u->role,'mustChangePassword'=>(bool)$u->must_change_password]:['loggedIn'=>false]);}
public function changePassword(Request $r){$u=$this->auth($r);if(!Hash::check($r->input('current_password',''),$u->password))return response()->json(['success'=>false,'message'=>'Current password is not correct.'],400);$p=$r->input('new_password','');if(strlen($p)<8)return response()->json(['success'=>false,'message'=>'Password must be at least 8 characters.'],400);DB::table('admins')->where('id',$u->id)->update(['password'=>Hash::make($p),'must_change_password'=>0]);return response()->json(['success'=>true,'message'=>'Password changed successfully.']);}
public function classes(Request $r){$this->auth($r);return response()->json(['success'=>true,'classes'=>DB::table('classes')->orderBy('class_name')->get()]);}
public function createClass(Request $r){$this->auth($r,true);$d=$r->validate(['class_name'=>'required|max:50']);DB::table('classes')->insert(['class_name'=>trim($d['class_name']),'created_at'=>now(),'updated_at'=>now()]);return response()->json(['success'=>true,'message'=>'Class added successfully.']);}
public function deleteClass(Request $r,$id){$this->auth($r,true);DB::table('classes')->where('id',$id)->delete();return response()->json(['success'=>true,'message'=>'Class deleted successfully.']);}
public function subjects(Request $r){$this->auth($r);return response()->json(['success'=>true,'subjects'=>DB::table('subjects')->orderBy('id')->get()]);}
public function createSubject(Request $r){$this->auth($r,true);$d=$r->validate(['subject_name'=>'required|max:150','subject_code'=>'required|max:50','full_marks'=>'required|numeric|min:1','class_name'=>'nullable|max:50','subject_type'=>'nullable|max:20']);$d['subject_type']=$d['subject_type']??'main';$d['created_at']=$d['updated_at']=now();$id=DB::table('subjects')->insertGetId($d);return response()->json(['success'=>true,'message'=>'Subject added successfully.','id'=>$id]);}
public function deleteSubject(Request $r,$id){$this->auth($r,true);DB::table('subjects')->where('id',$id)->delete();return response()->json(['success'=>true,'message'=>'Subject deleted successfully.']);}
public function exams(Request $r){$this->auth($r);return response()->json(['success'=>true,'exams'=>DB::table('exams')->orderByDesc('exam_year')->get()]);}
public function createExam(Request $r){$this->auth($r,true);$d=$r->validate(['exam_name'=>'required|max:150','exam_year'=>'required|integer','class_name'=>'required|max:50']);$d['created_at']=$d['updated_at']=now();$id=DB::table('exams')->insertGetId($d);return response()->json(['success'=>true,'message'=>'Exam added successfully.','id'=>$id]);}
public function deleteExam(Request $r,$id){$this->auth($r,true);DB::table('exams')->where('id',$id)->delete();return response()->json(['success'=>true,'message'=>'Exam deleted successfully.']);}
public function results(Request $r){$this->auth($r);$q=DB::table('students');foreach(['class_name','exam_name','status']as $k)if($r->filled($k))$q->where($k,$r->$k);if($r->filled('exam_year'))$q->where('exam_year',$r->exam_year);if($r->filled('search')){$x='%'.$r->search.'%';$q->where(fn($w)=>$w->where('name','like',$x)->orWhere('roll','like',$x)->orWhere('registration','like',$x));}return response()->json(['success'=>true,'results'=>$q->orderByDesc('id')->limit(20000)->get()]);}
public function result(Request $r,$id){$this->auth($r);$s=DB::table('students')->find($id);if(!$s)return response()->json(['success'=>false,'message'=>'Result not found.'],404);$rs=DB::table('results')->join('subjects','subjects.id','=','results.subject_id')->where('student_id',$id)->select('results.*','subjects.subject_name','subjects.subject_code','subjects.full_marks','subjects.subject_type')->get();return response()->json(['success'=>true,'student'=>$s,'results'=>$rs]);}
private function saveResult($exam,$student,$entries,$status,$id=null){$subs=DB::table('subjects')->where('class_name',$exam->class_name)->orderBy('id')->get();[$rows,$final]=$this->process($subs,$entries);$main=$subs->filter(fn($s)=>strtolower($s->subject_type)!=='fourth')->pluck('id')->all();if(count(array_diff($main,array_map(fn($x)=>$x->subject_id,$rows))))abort(response()->json(['success'=>false,'message'=>'Marks are missing for one or more main subjects.'],400));$d=['name'=>$student['name'],'roll'=>$student['roll'],'registration'=>$student['registration']??'','group_name'=>$student['group_name']??'','class_name'=>$exam->class_name,'exam_name'=>$exam->exam_name,'exam_year'=>$exam->exam_year,'status'=>$status,'final_gpa'=>$final[0],'final_grade'=>$final[1],'result_status'=>$final[2],'updated_at'=>now()];if($id){DB::table('students')->where('id',$id)->update($d);DB::table('results')->where('student_id',$id)->delete();$sid=$id;}else{$d['created_at']=now();$sid=DB::table('students')->insertGetId($d);}foreach($rows as $x)DB::table('results')->insert(['student_id'=>$sid,'subject_id'=>$x->subject_id,'marks'=>$x->marks,'grade'=>$x->grade,'grade_point'=>$x->grade_point,'is_fourth_subject'=>$x->is_fourth_subject,'created_at'=>now(),'updated_at'=>now()]);return[$sid,$final];}
public function createResult(Request $r){$this->auth($r);$e=DB::table('exams')->find($r->input('exam_id'));if(!$e)return response()->json(['success'=>false,'message'=>'Exam not found.'],404);$s=$r->input('student',[]);if(DB::table('students')->where(['class_name'=>$e->class_name,'exam_name'=>$e->exam_name,'exam_year'=>$e->exam_year,'roll'=>$s['roll']??''])->exists())return response()->json(['success'=>false,'message'=>'This roll already exists for this exam.'],409);[$id,$f]=$this->saveResult($e,$s,$r->input('results',[]),'draft');return response()->json(['success'=>true,'message'=>'Result saved successfully.','student_id'=>$id,'gpa'=>$f[0],'grade'=>$f[1],'result'=>$f[2]]);}
public function updateResult(Request $r,$id){$u=$this->auth($r);$s=DB::table('students')->find($id);if(!$s)return response()->json(['success'=>false,'message'=>'Result not found.'],404);if($s->status==='published'&&$u->role!=='admin')return response()->json(['success'=>false,'message'=>'Only an admin can edit a published result.'],403);$e=(object)['class_name'=>$s->class_name,'exam_name'=>$s->exam_name,'exam_year'=>$s->exam_year];[$sid,$f]=$this->saveResult($e,$r->input('student',[]),$r->input('results',[]),$s->status,$id);return response()->json(['success'=>true,'message'=>'Result updated successfully.','final_gpa'=>$f[0],'final_grade'=>$f[1],'result'=>$f[2]]);}
public function deleteResult(Request $r,$id){$this->auth($r,true);DB::table('students')->where('id',$id)->delete();return response()->json(['success'=>true,'message'=>'Result deleted successfully.']);}
public function publish(Request $r,$id){$this->auth($r,true);DB::table('students')->where('id',$id)->update(['status'=>'published','updated_at'=>now()]);return response()->json(['success'=>true,'message'=>'Result published successfully.']);}
public function unpublish(Request $r,$id){$this->auth($r,true);DB::table('students')->where('id',$id)->update(['status'=>'draft','updated_at'=>now()]);return response()->json(['success'=>true,'message'=>'Result moved back to draft.']);}
public function bulkDelete(Request $r){$this->auth($r,true);$n=DB::table('students')->where(['class_name'=>$r->class_name,'exam_name'=>$r->exam_name,'exam_year'=>$r->exam_year])->delete();return response()->json(['success'=>true,'message'=>'All selected results deleted successfully.','deleted_count'=>$n]);}
public function bulkPublish(Request $r){$this->auth($r,true);$n=DB::table('students')->where(['class_name'=>$r->class_name,'exam_name'=>$r->exam_name,'exam_year'=>$r->exam_year])->update(['status'=>$r->action==='unpublish'?'draft':'published','updated_at'=>now()]);return response()->json(['success'=>true,'message'=>$n.' result(s) updated.','changed'=>$n]);}
public function dashboardStats(Request $r){$this->auth($r);return response()->json(['success'=>true,'totalStudents'=>DB::table('students')->count(),'totalResults'=>DB::table('results')->distinct('student_id')->count('student_id'),'publishedResults'=>DB::table('students')->where('status','published')->count(),'draftResults'=>DB::table('students')->where('status','draft')->count(),'stats'=>['classes'=>DB::table('classes')->count(),'subjects'=>DB::table('subjects')->count(),'exams'=>DB::table('exams')->count()]]);}
private function report($q){$students=DB::table('students')->where(['class_name'=>$q['class_name'],'exam_name'=>$q['exam_name'],'exam_year'=>$q['exam_year']])->get();$subs=DB::table('subjects')->where('class_name',$q['class_name'])->orderBy('id')->get();$rs=DB::table('results')->whereIn('student_id',$students->pluck('id'))->get()->groupBy('student_id');$a=[];foreach($students as $s){$rr=$rs->get($s->id,collect());$a[]=['id'=>$s->id,'name'=>$s->name,'roll'=>$s->roll,'registration'=>$s->registration??'','group_name'=>$s->group_name??'','status'=>$s->status,'final_gpa'=>(float)$s->final_gpa,'final_grade'=>$s->final_grade,'result_status'=>$s->result_status,'total_marks'=>$rr->sum('marks'),'total_full_marks'=>$rr->sum('full_marks'),'merit_marks'=>$rr->sum('marks'),'marks'=>$rr->keyBy('subject_id')->map(fn($z)=>(float)$z->marks),'grades'=>$rr->keyBy('subject_id')->map(fn($z)=>$z->grade),'position'=>null];}$p=collect($a)->filter(fn($x)=>$x['result_status']==='Pass')->sortByDesc('merit_marks')->values();foreach($p as $i=>$x){$idx=array_search($x['id'],array_column($a,'id'));$a[$idx]['position']=$i+1;}usort($a,fn($x,$y)=>($x['position']??99999)<=>($y['position']??99999));return['meta'=>['class_name'=>$q['class_name'],'exam_name'=>$q['exam_name'],'exam_year'=>(int)$q['exam_year'],'group_name'=>$q['group_name']??'','merit_mode'=>'marks','total_students'=>count($a)],'subjects'=>$subs,'students'=>$a];}
public function reportOptions(Request $r){$this->auth($r);return response()->json(['success'=>true,'options'=>DB::table('students')->select('class_name','exam_name','exam_year')->groupBy('class_name','exam_name','exam_year')->orderByDesc('exam_year')->get()]);}
public function merit(Request $r){$this->auth($r);$d=$this->report($r->query());return response()->json(['success'=>true,'meta'=>$d['meta'],'students'=>array_map(fn($x)=>collect($x)->except(['marks','grades'])->all(),$d['students'])]);}
public function tabulation(Request $r){$this->auth($r);return response()->json(['success'=>true,...$this->report($r->query()),'school'=>['name'=>env('SCHOOL_NAME','School'),'address'=>env('SCHOOL_ADDRESS',''),'eiin'=>env('SCHOOL_EIIN','')]]);}
public function statistics(Request $r){$this->auth($r);$d=$this->report($r->query());$c=collect($d['students']);$p=$c->where('result_status','Pass');$g=[];foreach(['A+','A','A-','B','C','D','F']as $x)$g[$x]=$c->where('final_grade',$x)->count();return response()->json(['success'=>true,'meta'=>$d['meta'],'summary'=>['total_students'=>$c->count(),'passed'=>$p->count(),'failed'=>$c->count()-$p->count(),'pass_rate'=>$c->count()?round($p->count()*100/$c->count(),2):0,'published'=>$c->where('status','published')->count(),'draft'=>$c->where('status','draft')->count(),'highest_gpa'=>$c->max('final_gpa')??0,'lowest_gpa'=>$c->min('final_gpa')??0,'average_gpa'=>$p->count()?round($p->avg('final_gpa'),2):0,'toppers'=>$p->take(3)->values()],'grades'=>$g,'subjects'=>[],'groups'=>[]]);}
public function exportCsv(Request $r){$this->auth($r,true);$d=$this->report($r->query());$head=['Position','Roll','Name','Registration','Group'];foreach($d['subjects']as $s)$head[]=$s->subject_name.' ('.$s->subject_code.')';$head=array_merge($head,['Total Marks','GPA','Grade','Result','Status']);$o=fopen('php://temp','r+');fputcsv($o,$head);foreach($d['students']as $x){$row=[$x['position']??'',$x['roll'],$x['name'],$x['registration'],$x['group_name']];foreach($d['subjects']as $s)$row[]=$x['marks'][$s->id]??'';$row[]=$x['total_marks'];$row[]=number_format($x['final_gpa'],2);$row[]=$x['final_grade'];$row[]=$x['result_status'];$row[]=$x['status'];fputcsv($o,$row);}rewind($o);return response(stream_get_contents($o),200,['Content-Type'=>'text/csv','Content-Disposition'=>'attachment; filename="results.csv"']);}
public function exportXlsx(Request $r){$this->auth($r,true);$d=$this->report($r->query());$w=new Spreadsheet();$s=$w->getActiveSheet();$head=['Position','Roll','Name','Registration','Group'];foreach($d['subjects']as $x)$head[]=$x->subject_name.' ('.$x->subject_code.')';$head=array_merge($head,['Total Marks','GPA','Grade','Result','Status']);$s->fromArray([$head]);foreach($d['students']as $x){$row=[$x['position']??'',$x['roll'],$x['name'],$x['registration'],$x['group_name']];foreach($d['subjects']as $sub)$row[]=$x['marks'][$sub->id]??'';$row[]=$x['total_marks'];$row[]=number_format($x['final_gpa'],2);$row[]=$x['final_grade'];$row[]=$x['result_status'];$row[]=$x['status'];$s->fromArray([$row]);}$wrt=new Xlsx($w);ob_start();$wrt->save('php://output');$o=ob_get_clean();return response($o,200,['Content-Type'=>'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','Content-Disposition'=>'attachment; filename="results.xlsx"']);}
public function backup(Request $r){$this->auth($r,true);return response()->json(['app'=>'school-result-system','version'=>2,'created_at'=>now()->toIso8601String(),'exams'=>DB::table('exams')->get(),'subjects'=>DB::table('subjects')->get(),'students'=>DB::table('students')->get(),'results'=>DB::table('results')->get()],200,['Content-Disposition'=>'attachment; filename="result-backup.json"']);}
public function users(Request $r){$this->auth($r,true);return response()->json(['success'=>true,'users'=>DB::table('admins')->select('id','username','role','active','must_change_password','last_login','created_at')->get()]);}
public function createUser(Request $r){$this->auth($r,true);$d=$r->validate(['username'=>'required|regex:/^[A-Za-z0-9._-]{3,50}$/','password'=>'required|min:8','role'=>'required|in:admin,teacher']);$id=DB::table('admins')->insertGetId(['username'=>$d['username'],'password'=>Hash::make($d['password']),'role'=>$d['role'],'active'=>1,'must_change_password'=>1,'created_at'=>now(),'updated_at'=>now()]);return response()->json(['success'=>true,'message'=>'User created.','id'=>$id]);}
public function updateUser(Request $r,$id){$this->auth($r,true);$u=DB::table('admins')->find($id);if(!$u)return response()->json(['success'=>false,'message'=>'User not found.'],404);DB::table('admins')->where('id',$id)->update(['role'=>$r->input('role',$u->role),'active'=>$r->has('active')?$r->boolean('active'):$u->active]);return response()->json(['success'=>true,'message'=>'User updated.']);}
public function resetPassword(Request $r,$id){$this->auth($r,true);$p=$r->input('new_password','');if(strlen($p)<8)return response()->json(['success'=>false,'message'=>'Password must be at least 8 characters.'],400);DB::table('admins')->where('id',$id)->update(['password'=>Hash::make($p),'must_change_password'=>1]);return response()->json(['success'=>true,'message'=>'Password reset.']);}
public function audit(Request $r){$this->auth($r,true);$q=DB::table('audit_log')->orderByDesc('id');return response()->json(['success'=>true,'total'=>$q->count(),'logs'=>$q->limit(min(200,max(1,(int)$r->input('limit',50))))->get(),'actions'=>DB::table('audit_log')->distinct()->pluck('action')]);}
private function pub($q){$s=DB::table('students')->where(['roll'=>$q['roll'],'class_name'=>$q['class_name'],'exam_name'=>$q['exam_name'],'exam_year'=>$q['exam_year'],'status'=>'published'])->first();if(!$s)abort(response()->json(['success'=>false,'message'=>'Result not found or result has not been published.'],404));return $s;}
private function pdata($s){$rs=DB::table('results')->join('subjects','subjects.id','=','results.subject_id')->where('student_id',$s->id)->select('results.*','subjects.subject_name','subjects.subject_code','subjects.full_marks','subjects.subject_type')->get();[$g,$gr,$st]=$this->finalGpa($rs);return['student'=>$s,'school'=>['name'=>env('SCHOOL_NAME','School'),'address'=>env('SCHOOL_ADDRESS',''),'eiin'=>env('SCHOOL_EIIN','')],'subjects'=>$rs,'summary'=>['total_marks'=>$rs->sum('marks'),'total_full_marks'=>$rs->sum('full_marks'),'gpa'=>$g,'grade'=>$gr,'result'=>$st,'position'=>'-'],'verify_url'=>url('/verify/'.((int)$s->id).'/'.hash_hmac('sha256',(string)$s->id,env('APP_KEY')))];}
public function publicOptions(){return response()->json(['success'=>true,'options'=>DB::table('students')->where('status','published')->select('class_name','exam_name','exam_year')->groupBy('class_name','exam_name','exam_year')->orderBy('class_name')->get()]);}
public function publicSearch(Request $r){$s=$this->pub($r->query());return response()->json(['success'=>true,...$this->pdata($s)]);}
public function publicPdf(Request $r){$s=$this->pub($r->query());$d=$this->pdata($s);$qr=(new Builder())->data($d['verify_url'])->size(300)->margin(1)->build();$d['qr_data']='data:image/png;base64,'.base64_encode($qr->getString());return Pdf::loadView('marksheet-pdf',['data'=>$d])->setOption(['isRemoteEnabled'=>false])->stream('marksheet-'.$s->roll.'.pdf');}
public function verify(Request $r,$id,$sig){if(!hash_equals(hash_hmac('sha256',(string)$id,env('APP_KEY')), $sig))abort(404);$s=DB::table('students')->where(['id'=>$id,'status'=>'published'])->first();if(!$s)abort(404);return view('verify',['data'=>$this->pdata($s)]);}
public function marksheetsPdf(Request $r){$this->auth($r);return Pdf::loadView('marksheet-pdf',['data'=>$this->report($r->query())])->stream('marksheets.pdf');}
public function bulkPreview(Request $r){$this->auth($r);$f=$r->file('excelFile');if(!$f)return response()->json(['success'=>false,'message'=>'Please select an Excel file.'],400);$rows=IOFactory::load($f->getRealPath())->getActiveSheet()->toArray();$head=array_map('trim',array_shift($rows));$raw=[];foreach($rows as $row){$d=array_combine($head,array_pad($row,count($head),''));if(count(array_filter($row,fn($v)=>$v!==null&&$v!=='')))$raw[]=$d;}$exam=DB::table('exams')->find($r->input('exam_id'));$analysis=[];$new=0;$update=0;$skipped=0;$invalid=0;if($exam){$subs=DB::table('subjects')->where('class_name',$exam->class_name)->get();foreach($raw as $i=>$d){$name=trim((string)($d['Name']??''));$roll=trim((string)($d['Roll']??''));$errors=[];$state='new';$existing=$roll?DB::table('students')->where(['class_name'=>$exam->class_name,'exam_name'=>$exam->exam_name,'exam_year'=>$exam->exam_year,'roll'=>$roll])->first():null;if($existing){if(($r->input('duplicate_mode')??'skip')==='update'){$state='update';$update++;}else{$state='skip';$errors[]='This roll already exists for this exam (skipped).';$skipped++;}}foreach($subs as $s){$v=$d[$s->subject_name]??'';if($v===''&&strtolower($s->subject_type)!=='fourth')$errors[]=$s->subject_name.' marks are missing.';elseif($v!==''&&$v!=='-'&&!is_numeric($v))$errors[]=$s->subject_name.' marks are not a valid number.';elseif($v!==''&&$v!=='-'&&(float)$v<0)$errors[]=$s->subject_name.' marks are invalid.'; }if(!$name)$errors[]='Student name is missing.';if(!$roll)$errors[]='Roll is missing.';$valid=count($errors)===0;if($valid&&$state==='new')$new++;if(!$valid&&$state!=='skip')$invalid++;$analysis[]=['row'=>$i+2,'name'=>$name,'roll'=>$roll,'registration'=>$d['Registration']??'','valid'=>$valid,'state'=>$state,'errors'=>$errors,'gpa'=>null,'grade'=>null,'result'=>null];}}else{$invalid=count($raw);foreach($raw as $i=>$d)$analysis[]=['row'=>$i+2,'name'=>$d['Name']??'','roll'=>$d['Roll']??'','registration'=>$d['Registration']??'','valid'=>true,'state'=>'new','errors'=>[],'gpa'=>null,'grade'=>null,'result'=>null];$new=count($raw);}return response()->json(['success'=>true,'total_rows'=>count($raw),'columns'=>$head,'rows'=>$raw,'counts'=>['total'=>count($analysis),'new'=>$new,'update'=>$update,'skipped'=>$skipped,'invalid'=>$invalid],'analysis'=>$analysis]);}
public function bulkImport(Request $r){$this->auth($r);$f=$r->file('excelFile');$e=DB::table('exams')->find($r->input('exam_id'));if(!$f||!$e)return response()->json(['success'=>false,'message'=>'Excel file and exam are required.'],400);$rows=IOFactory::load($f->getRealPath())->getActiveSheet()->toArray();$head=array_shift($rows);$subs=DB::table('subjects')->where('class_name',$e->class_name)->get();$ok=0;$bad=0;$errors=[];foreach($rows as $i=>$row){$d=array_combine($head,array_pad($row,count($head),''));$name=trim((string)($d['Name']??''));$roll=trim((string)($d['Roll']??''));if(!$name||!$roll){$bad++;$errors[]=['row'=>$i+2,'error'=>'Name and Roll are required.'];continue;}$entries=[];$skip=false;foreach($subs as $s){$v=$d[$s->subject_name]??'';if($v===''&&strtolower($s->subject_type)!=='fourth'){$skip=true;$errors[]=['row'=>$i+2,'error'=>$s->subject_name.' marks are missing.'];break;}if($v!==''&&$v!=='-')$entries[]=['subject_id'=>$s->id,'marks'=>$v];}if($skip){$bad++;continue;}try{$old=DB::table('students')->where(['class_name'=>$e->class_name,'exam_name'=>$e->exam_name,'exam_year'=>$e->exam_year,'roll'=>$roll])->first();$this->saveResult($e,['name'=>$name,'roll'=>$roll,'registration'=>$d['Registration']??'','group_name'=>$d['Group']??''],$entries,'published',$old? $old->id:null);$ok++;}catch(\Throwable $x){$bad++;$errors[]=['row'=>$i+2,'error'=>$x->getMessage()];}}return response()->json(['success'=>true,'message'=>'Import completed.','total'=>count($rows),'processed'=>$ok,'created'=>$ok,'updated'=>0,'failed'=>$bad,'errors'=>$errors,'published'=>true]);}
public function downloadExcelDemo(Request $r){$e=DB::table('exams')->find($r->input('exam_id'));$subs=$e?DB::table('subjects')->where('class_name',$e->class_name)->get():collect();$w=new Spreadsheet();$w->getActiveSheet()->fromArray([['Name','Roll','Registration','Group',...$subs->pluck('subject_name')->all()]]);$x=new Xlsx($w);ob_start();$x->save('php://output');$o=ob_get_clean();return response($o,200,['Content-Type'=>'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','Content-Disposition'=>'attachment; filename="result-template.xlsx"']);}
}